#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_runtime.h>
// Persistent fused LayerNorm kernel. This optimization keeps the fused
// per-row release protocol, but changes the work partition so one block owns
// one feature slice and loops over all rows for that slice. The weight/bias
// slice is staged once in dynamic shared memory and reused for every row,
// instead of being re-read from DRAM for each row. For the target shape
// (rows=16, N=64*256*256) this removes the large repeated w/b DRAM stream
// while keeping x vectorized and y stores streaming.
__global__ void layernorm_fused_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    double* __restrict__ rowsum,
    double* __restrict__ rowsumsq,
    unsigned int* __restrict__ rowcount,
    unsigned int* __restrict__ rowready,
    float* __restrict__ y,
    const long long N,
    const long long rows,
    const long long items,
    const long long slices,
    const long long slice_len,
    const float eps) {
  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;
  const int lane = tid & 31;
  const int warp = tid >> 5;
  const int nwarps = (nthreads + 31) >> 5;
  const bool vec_ok = ((N & 3LL) == 0LL);
  __shared__ double ssum[32];
  __shared__ double ssq[32];
  extern __shared__ float swb[];
  float* sw = swb;
  float* sb = swb + slice_len;
  // Phase 1: for each owned feature slice, compute partial sums for all rows.
  // A row is released exactly when the last slice contributing to that row
  // has atomically accumulated its partial sums.
  for (long long item = blockIdx.x; item < items; item += gridDim.x) {
    const long long slice = item;
    const long long start = slice * slice_len;
    long long end = start + slice_len;
    if (end > N) end = N;
    if (start >= end) continue;
    const long long len = end - start;
    for (long long row = 0; row < rows; ++row) {
      double sum = 0.0;
      double sumsq = 0.0;
      const float* xrow = x + row * N;
      if (vec_ok) {
        const float4* x4 = reinterpret_cast<const float4*>(xrow);
        const long long vbegin = start >> 2;
        const long long vend = end >> 2;
        for (long long i = vbegin + (long long)tid * 2LL; i < vend; i += (long long)nthreads * 2LL) {
          const float4 v0 = x4[i];
          sum += (double)v0.x + (double)v0.y + (double)v0.z + (double)v0.w;
          sumsq += (double)v0.x * (double)v0.x + (double)v0.y * (double)v0.y +
                   (double)v0.z * (double)v0.z + (double)v0.w * (double)v0.w;
          if (i + 1LL < vend) {
            const float4 v1 = x4[i + 1LL];
            sum += (double)v1.x + (double)v1.y + (double)v1.z + (double)v1.w;
            sumsq += (double)v1.x * (double)v1.x + (double)v1.y * (double)v1.y +
                     (double)v1.z * (double)v1.z + (double)v1.w * (double)v1.w;
          }
        }
      } else {
        for (long long i = tid; i < len; i += nthreads) {
          const double v = (double)xrow[start + i];
          sum += v;
          sumsq += v * v;
        }
      }
      for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffffu, sum, offset);
        sumsq += __shfl_down_sync(0xffffffffu, sumsq, offset);
      }
      if (lane == 0) {
        ssum[warp] = sum;
        ssq[warp] = sumsq;
      }
      __syncthreads();
      if (warp == 0) {
        double tsum = (lane < nwarps) ? ssum[lane] : 0.0;
        double tsq = (lane < nwarps) ? ssq[lane] : 0.0;
        for (int offset = 16; offset > 0; offset >>= 1) {
          tsum += __shfl_down_sync(0xffffffffu, tsum, offset);
          tsq += __shfl_down_sync(0xffffffffu, tsq, offset);
        }
        if (lane == 0) {
          atomicAdd(&rowsum[row], tsum);
          atomicAdd(&rowsumsq[row], tsq);
          __threadfence();
          const unsigned int done = atomicAdd(&rowcount[row], 1u) + 1u;
          if (done == (unsigned int)slices) {
            __threadfence();
            atomicExch(&rowready[row], 1u);
          }
        }
      }
      __syncthreads();
    }
  }
  // Phase 2: for each owned slice, stage w/b once in shared memory, then apply
  // that same affine slice to every row after that row's statistics are ready.
  for (long long item = blockIdx.x; item < items; item += gridDim.x) {
    const long long slice = item;
    const long long start = slice * slice_len;
    long long end = start + slice_len;
    if (end > N) end = N;
    if (start >= end) continue;
    const long long len = end - start;
    for (long long i = tid; i < len; i += nthreads) {
      sw[i] = w[start + i];
      sb[i] = b[start + i];
    }
    __syncthreads();
    for (long long row = 0; row < rows; ++row) {
      if (tid == 0) {
        while (atomicAdd(&rowready[row], 0u) == 0u) {
        }
        __threadfence();
      }
      __syncthreads();
      const double mean = rowsum[row] / (double)N;
      double var = rowsumsq[row] / (double)N - mean * mean;
      if (var < 0.0) var = 0.0;
      const float meanf = (float)mean;
      const float rstd = rsqrtf((float)var + eps);
      const float* xrow = x + row * N;
      float* yrow = y + row * N;
      if (vec_ok) {
        const float4* x4 = reinterpret_cast<const float4*>(xrow);
        float4* y4 = reinterpret_cast<float4*>(yrow);
        const long long vbegin = start >> 2;
        const long long vend = end >> 2;
        for (long long i = vbegin + tid; i < vend; i += nthreads) {
          const long long j = (i << 2) - start;
          const float4 xv = x4[i];
          float4 out;
          out.x = (xv.x - meanf) * rstd * sw[j + 0] + sb[j + 0];
          out.y = (xv.y - meanf) * rstd * sw[j + 1] + sb[j + 1];
          out.z = (xv.z - meanf) * rstd * sw[j + 2] + sb[j + 2];
          out.w = (xv.w - meanf) * rstd * sw[j + 3] + sb[j + 3];
          __stwt(&y4[i], out);
        }
      } else {
        for (long long i = tid; i < len; i += nthreads) {
          __stwt(&yrow[start + i], (xrow[start + i] - meanf) * rstd * sw[i] + sb[i]);
        }
      }
    }
  }
}
torch::Tensor layernorm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat && bias.scalar_type() == at::kFloat,
              "weight/bias must be float32");
  auto xc = x.contiguous();
  auto wc = weight.contiguous();
  auto bc = bias.contiguous();
  const long long N = (long long)wc.numel();
  TORCH_CHECK(N > 0, "normalized_shape numel must be positive");
  TORCH_CHECK(xc.numel() % N == 0, "input trailing dims must match normalized_shape");
  const long long rows = (long long)xc.numel() / N;
  auto y = at::empty_like(xc);
  if (rows == 0) return y;
  auto stream = at::cuda::getCurrentCUDAStream();
  const int num_sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
  const int threads = 256;
  // Keep one feature slice per block small enough to stage w+b in shared memory.
  const long long target_slice = 4096LL;
  long long slices = (N + target_slice - 1LL) / target_slice;
  if (slices < 1) slices = 1;
  long long slice_len = (N + slices - 1LL) / slices;
  slice_len = (slice_len + 3LL) & ~3LL;  // keep 16B alignment of slice starts
  slices = (N + slice_len - 1LL) / slice_len;
  if (slices < 1) slices = 1;
  const size_t smem_bytes = (size_t)(2LL * slice_len) * sizeof(float);
  int blocks_per_sm = 0;
  C10_CUDA_CHECK(cudaOccupancyMaxActiveBlocksPerMultiprocessor(
      &blocks_per_sm, layernorm_fused_kernel, threads, (int)smem_bytes));
  if (blocks_per_sm < 1) blocks_per_sm = 1;
  const long long maxblocks = (long long)num_sms * (long long)blocks_per_sm;
  const long long items = slices;
  long long grid = items < maxblocks ? items : maxblocks;
  if (grid < 1LL) grid = 1LL;
  // One fused zero-initialized allocation:
  // [rowsum | rowsumsq | rowcount(uint in 8B slots) | rowready(uint in 8B slots)].
  auto stats = at::zeros({4 * rows}, xc.options().dtype(at::kDouble));
  double* stats_ptr = stats.data_ptr<double>();
  double* rowsum = stats_ptr;
  double* rowsumsq = stats_ptr + rows;
  unsigned int* rowcount = reinterpret_cast<unsigned int*>(stats_ptr + 2 * rows);
  unsigned int* rowready = reinterpret_cast<unsigned int*>(stats_ptr + 3 * rows);
  layernorm_fused_kernel<<<(unsigned int)grid, threads, smem_bytes, stream>>>(
      xc.data_ptr<float>(),
      wc.data_ptr<float>(),
      bc.data_ptr<float>(),
      rowsum,
      rowsumsq,
      rowcount,
      rowready,
      y.data_ptr<float>(),
      N,
      rows,
      items,
      slices,
      slice_len,
      (float)eps);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return y;
}
"""
