_layernorm_ext = load_inline(
    name="custom_layernorm_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["layernorm_cuda"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
